let master=World.fresh(),career=null,mode='home',s=World.context(master),view='Centro de comando',division=1,editorClub=12,editTarget=null;const $=id=>document.getElementById(id),esc=x=>String(x).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c])),money=n=>new Intl.NumberFormat('pt-PT',{style:'currency',currency:'CHF',maximumFractionDigits:0}).format(n),club=id=>s.clubs.find(c=>c.id===id),league=d=>Engine.competition(s,d).name;const badge=c=>`<span class="badge ${c.logo?'has-logo':''}" style="--club:${c.color}">${clubMark(c)}</span>`;const options=(arr,current)=>arr.map(x=>`<option value="${esc(x)}" ${x===current?'selected':''}>${esc(x)}</option>`).join('');const clubOptions=id=>s.clubs.map(c=>`<option value="${c.id}" ${c.id===id?'selected':''}>${esc(c.name)}</option>`).join('');const managedClubOptions=id=>s.clubs.filter(c=>[0,1].includes(c.div)).map(c=>`<option value="${c.id}" ${c.id===id?'selected':''}>${esc(c.name)} · ${esc(league(c.div))}</option>`).join('');const editorClubOptions=id=>clubOptions(id)+`<option value="free" ${id==='free'?'selected':''}>— Sem clube —</option>`;const divisionLabel=c=>c.div===0?'1.º escalão · Super League':c.div===1?'2.º escalão · Challenge League':c.div===2?'3.º escalão · Promotion League':`Futebol amador · nível ${c.tier||4}`;
function message(t){$('notice').textContent=t;}
function standings(d,short=false){return `<div class="table-wrap"><table><thead><tr><th>#</th><th>CLUBE</th><th>J</th>${short?'':'<th>V</th><th>E</th><th>D</th><th>GM</th><th>GS</th>'}<th>DG</th><th>PTS</th></tr></thead><tbody>${Engine.table(s,d).map((c,i)=>`<tr class="${c.id===s.managed?'mine ':''}${d===1&&i===0?'promotion':d===0&&i===11?'relegation':''}"><td>${i+1}</td><td>${badge(c)}<button class="player-name" data-club="${c.id}">${esc(c.name)}</button></td><td>${c.p}</td>${short?'':`<td>${c.w}</td><td>${c.draw}</td><td>${c.l}</td><td>${c.gf}</td><td>${c.ga}</td>`}<td>${c.gf-c.ga}</td><td><b>${c.pts}</b></td></tr>`).join('')}</tbody></table></div>`;}
function match(m){return `<div class="match"><span>${esc(club(m.home).name)}${headCoach(m.home)?`<small class="coach-name">${esc(headCoach(m.home).name)}</small>`:''}</span><b class="score">${m.hg===null?'—':m.hg+' : '+m.ag}</b><span>${esc(club(m.away).name)}${headCoach(m.away)?`<small class="coach-name">${esc(headCoach(m.away).name)}</small>`:''}</span>${m.report?`<button data-report-home="${m.home}" data-report-away="${m.away}">Relatório</button>`:''}</div>`;}
