function cupCareerPanel(competitionId=2){const comp=Engine.cupCompetition(s,competitionId),state=Engine.cupState(s,competitionId);if(!comp||!state)return '';const round=state.rounds[state.stage],winner=state.winner===null?null:club(state.winner),official=competitionId===2,ruleText=official?'Eliminatória a um jogo. Em caso de empate: prolongamento e penáltis. A equipa de escalão inferior tem vantagem de jogar em casa até às meias-finais; na 2.ª ronda são evitados duelos entre equipas da Super League.':'Eliminatória a um jogo. Em caso de empate, o motor decide o vencedor após prolongamento e, se necessário, penáltis.';return `<section class="panel cup-career" style="margin-top:22px"><div class="competition-card-head"><div class="competition-identity">${competitionMark(comp)}<div><span class="eyebrow">${official?'TAÇA OFICIAL':'TAÇA CRIADA'} · MOTOR ACTIVO</span><h2>${esc(comp.name)}</h2><p class="muted">${esc(comp.officialName||comp.shortName||'')} · ${competitionParticipants(comp,s).length} participantes</p></div></div>${competitionMark(comp,'trophy')}</div>${state.finished?`<div class="cup-winner"><span>VENCEDOR ${s.year}/${String(s.year+1).slice(-2)}</span><strong>${badge(winner)}${esc(winner.name)}</strong></div>`:`<div class="panel-head"><div><span class="eyebrow">${esc(round.name.toUpperCase())}</span><h3>${esc(round.date||'Eliminatória')}</h3></div><button data-play-cup="${competitionId}" class="primary">Simular eliminatória →</button></div><p class="muted">${esc(ruleText)}</p>`}<div class="cup-round-list">${round.matches.map((m,i)=>cupMatch(m,competitionId,state.stage,i)).join('')}</div>${state.stage?`<details><summary>Rondas anteriores</summary>${state.rounds.slice(0,state.stage).reverse().map(r=>`<h4>${esc(r.name)} ${r.date?`· ${esc(r.date)}`:''}</h4>${r.matches.map((m,i)=>cupMatch(m,competitionId,r.index,i)).join('')}`).join('')}</details>`:''}</section>`;}
function feederCareerPanel(){const c=s.competitions?.find(c=>c.id===3),clubs=s.clubs.filter(x=>x.div===2);if(!c||!clubs.length)return '';const eligible=clubs.filter(x=>x.promotionEligible!==false&&!x.reserveTeam);return `<section class="panel" style="margin-top:22px"><div class="panel-head"><div><span class="eyebrow">3.º ESCALÃO</span><h2>${esc(c.name)}</h2></div><span class="tag">${clubs.length} clubes</span></div><p class="muted">Bolsa de promoção para a Challenge League. No fim da época, o motor simula a classificação deste escalão e promove o melhor clube elegível; equipas U-21 não podem subir.</p><div class="feeder-clubs">${clubs.map(x=>`<span class="chip ${x.promotionEligible===false||x.reserveTeam?'muted':''}">${esc(x.name)}${x.promotionEligible===false||x.reserveTeam?' · não elegível':''}</span>`).join('')}</div><p class="muted">${eligible.length} clubes actualmente elegíveis para promoção.</p></section>`;}
